UPDATE `acore_string` SET
`content_default` = 'In order to complete setup, you\'ll need to set up the device you\'ll be using as your second factor.\nYour 2FA key: {}\nAdd the key to an authenticator app, such as the free and open source FreeOTP (https://freeotp.github.io/), with these settings:\n- Type: Time-based (TOTP)\n- Digits: 6\n- Algorithm: SHA1\n- Interval: 30 seconds\nOnce you have set up your device, confirm by running .account 2fa setup <token> with the generated token.',
`locale_deDE` = 'Um die Einrichtung abzuschließen, müsst Ihr das Gerät einrichten, das Ihr als zweiten Faktor verwenden werdet.\nEuer 2FA-Schlüssel: {}\nFügt den Schlüssel einer Authenticator-App hinzu, zum Beispiel dem freien und quelloffenen FreeOTP (https://freeotp.github.io/), mit diesen Einstellungen:\n- Typ: Zeitbasiert (TOTP)\n- Ziffern: 6\n- Algorithmus: SHA1\n- Intervall: 30 Sekunden\nSobald Ihr Euer Gerät eingerichtet habt, bestätigt dies mit .account 2fa setup <token> und dem generierten Token.',
`locale_esES` = 'Para completar la configuración, tendrás que configurar el dispositivo que utilizarás como segundo factor.\nSu clave 2FA: {}\nAñade la clave a una aplicación de autenticación, como FreeOTP, libre y de código abierto (https://freeotp.github.io/), con estos ajustes:\n- Tipo: Basado en tiempo (TOTP)\n- Dígitos: 6\n- Algoritmo: SHA1\n- Intervalo: 30 segundos\nUna vez que hayas configurado tu dispositivo, confirma ejecutando .account 2fa setup <token> con el token generado.',
`locale_esMX` = 'Para completar la configuración, tendrás que configurar el dispositivo que utilizarás como segundo factor.\nSu clave 2FA: {}\nAñade la clave a una aplicación de autenticación, como FreeOTP, libre y de código abierto (https://freeotp.github.io/), con estos ajustes:\n- Tipo: Basado en tiempo (TOTP)\n- Dígitos: 6\n- Algoritmo: SHA1\n- Intervalo: 30 segundos\nUna vez que hayas configurado tu dispositivo, confirma ejecutando .account 2fa setup <token> con el token generado.'
WHERE `entry` = 91;
